cat > /tmp/val.sh <<'EOF'
get(){ p=$1; db=$2; k=$3; t=$4
 case $t in
  string) redis-cli -p $p -n $db get "$k";;
  list) redis-cli -p $p -n $db lrange "$k" 0 -1;;
  set) redis-cli -p $p -n $db smembers "$k" | sort;;
  zset) redis-cli -p $p -n $db zrange "$k" 0 -1 withscores;;
  hash) redis-cli -p $p -n $db hgetall "$k" | paste - - | sort;;
  stream) redis-cli -p $p -n $db xrange "$k" - +; redis-cli -p $p -n $db xinfo stream "$k" | grep -v -A1 -E 'radix|recorded' ;
     for g in $(redis-cli -p $p -n $db xinfo groups "$k" | awk 'prev=="name"{print} {prev=$0}'); do redis-cli -p $p -n $db xinfo consumers "$k" "$g" | grep -v -A1 -E 'idle|inactive' ; redis-cli -p $p -n $db xpending "$k" "$g" - + 1000 | awk 'NR%4!=3'; done;;
  *) echo OTHER $t;;
 esac | md5sum; }
n=0; bad=0
for db in 0 2; do for k in $(redis-cli -p 6379 -n $db --scan); do
 t=$(redis-cli -p 6379 -n $db type "$k"); n=$((n+1))
 [ "$(get 6379 $db "$k" $t)" != "$(get 6380 $db "$k" $t)" ] && { echo "VALDIFF db$db $k $t"; bad=$((bad+1)); }
done; done; echo checked=$n bad=$bad
EOF
bash /tmp/val.sh | tail -5; for db in 0 2; do redis-cli -p 6379 -n $db --scan | xargs -n1 redis-cli -p 6379 -n $db type | sort | uniq -c; done
